<?php include "auth.php";include "conection.php";$error='';if($_SERVER['REQUEST_METHOD']==='POST'){$nama=trim($_POST['nama_kategori']??'');$ket=trim($_POST['keterangan']??'');if($nama==='')$error='Nama kategori wajib diisi.';else{$s=$conn->prepare("INSERT INTO kategori(nama_kategori,keterangan) VALUES(?,?)");$s->bind_param("ss",$nama,$ket);if($s->execute()){header("Location: kategori.php");exit;}$error="Gagal menyimpan: ".$s->error;}}?>
